const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.1",
  "engineVersion": "d1b3f377ca835d73fd50954a5e22128b9ebdd6b8",
  "activeProvider": "postgresql",
  "inlineSchema": "// LogiDesk — multi-tenant document collection & client portal.\n// Source of truth: docs/Product_Specification.md (Sections 3–15) and app/mockups.\n//\n// Conventions\n// - UUID primary keys everywhere (Postgres `uuid`), snake_case columns, plural snake_case tables.\n// - Every organization-owned row carries `organization_id`; Postgres row-level security policies\n//   (shipped in the migrations folder) filter on that column using the `app.current_organization_id`\n//   session setting. Backend queries are organization-scoped as well.\n// - Soft deletion / archival via `deleted_at` / `archived_at` where history matters.\n// - Actors: employees are `User`s acting through an `OrganizationMember`; portal users are\n//   `ClientUser`s; background jobs are `SYSTEM`. Audit columns carry one of each where relevant.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Enums\n// ───────────────────────────────────────────────────────────────────────────────\n\n/// Platform-level account role (support / super-admin tooling). Workspace permissions\n/// live on OrganizationMember.role.\nenum AuthRole {\n  USER\n  ADMIN\n  SUPER_ADMIN\n  SUPPORT\n}\n\nenum OrganizationRole {\n  OWNER\n  ADMIN\n  MEMBER\n}\n\nenum MembershipStatus {\n  ACTIVE\n  SUSPENDED\n}\n\nenum InvitationType {\n  TEAM\n  CLIENT\n}\n\nenum InvitationStatus {\n  PENDING\n  ACCEPTED\n  REVOKED\n  EXPIRED\n}\n\n/// Which principal a session was issued for. Workspace (employee) and portal (client)\n/// sessions are never interchangeable.\nenum SessionKind {\n  WORKSPACE\n  PORTAL\n}\n\nenum ClientStatus {\n  ACTIVE\n  ARCHIVED\n}\n\nenum ClientUserStatus {\n  INVITED\n  ACTIVE\n  DISABLED\n}\n\nenum PortalAccessMode {\n  PRIVATE\n  PUBLIC\n}\n\nenum FormStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\nenum FormVersionStatus {\n  DRAFT\n  PUBLISHED\n}\n\n/// Field types supported by the form builder. Field definitions live in FormVersion.definition\n/// (JSON); the enum is exported so the API validates the JSON against one source of truth.\nenum FormFieldType {\n  SHORT_TEXT\n  LONG_TEXT\n  NUMBER\n  EMAIL\n  PHONE\n  DATE\n  DROPDOWN\n  MULTIPLE_CHOICE\n  CHECKBOXES\n  FILE_UPLOAD\n  YES_NO\n  HEADING\n  DESCRIPTION\n  DIVIDER\n}\n\n/// Accepted file format groups shown to users (never individual image extensions).\nenum FileFormat {\n  PDF\n  IMAGE\n  WORD\n  EXCEL\n}\n\nenum ExpirationPolicy {\n  NONE\n  MANUAL\n  FROM_UPLOAD_DATE\n  FIXED_DATE\n}\n\n/// Where an uploaded document's expiration date came from.\nenum ExpirationSource {\n  MANUAL\n  CALCULATED\n  FIXED\n  EXTRACTED\n}\n\nenum ReminderIntervalUnit {\n  DAYS\n  WEEKS\n  HOURS\n}\n\nenum AssignmentStatus {\n  NOT_STARTED\n  IN_PROGRESS\n  UNDER_REVIEW\n  COMPLETE\n  OVERDUE\n  CANCELLED\n}\n\n/// Effective lifecycle status of a document requirement inside an assignment.\n/// Cached on AssignmentRequirement.status; recomputed from the latest submission's\n/// review state and dates (never overwrites document history).\nenum RequirementStatus {\n  MISSING\n  SUBMITTED\n  UNDER_REVIEW\n  APPROVED\n  REJECTED\n  EXPIRED\n  NOT_REQUIRED\n}\n\nenum FormResponseStatus {\n  DRAFT\n  SUBMITTED\n}\n\nenum UploadSource {\n  EMPLOYEE_UPLOAD\n  CLIENT_PORTAL\n  EMAIL\n  PUBLIC_PORTAL\n}\n\nenum ReviewStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum DocumentVersionChangeType {\n  CREATED\n  FILE_REPLACED\n  METADATA_UPDATED\n  EXPIRATION_CHANGED\n  REVIEW_CHANGED\n  RESTORED\n}\n\nenum InboxProcessingStatus {\n  RECEIVED\n  PROCESSING\n  MATCHED\n  NEEDS_REVIEW\n  UNMATCHED\n  FAILED\n  DUPLICATE\n  RESOLVED\n}\n\nenum MatchConfidence {\n  HIGH\n  MEDIUM\n  LOW\n}\n\nenum InboxReviewAction {\n  CONFIRMED\n  CHANGED\n  DISMISSED\n  APPROVED\n  REJECTED\n}\n\nenum PublicSubmissionStatus {\n  PENDING_REVIEW\n  ACCEPTED\n  DISMISSED\n}\n\nenum NotificationChannel {\n  EMAIL\n  SMS\n}\n\nenum EmailProvider {\n  RESEND\n  SMTP\n}\n\nenum SmsProvider {\n  TWILIO\n}\n\nenum NotificationType {\n  FORM_ASSIGNED\n  MISSING_DOCUMENTS\n  EXPIRING_DOCUMENTS\n  EXPIRED_DOCUMENTS\n  DOCUMENT_REJECTED\n  DOCUMENT_APPROVED\n  CLIENT_INVITATION\n  TEAM_INVITATION\n  EMAIL_VERIFICATION\n  PASSWORD_RESET\n  MANUAL_REMINDER\n  EMPLOYEE_ALERT\n  CUSTOM\n}\n\nenum NotificationStatus {\n  PENDING\n  SENT\n  DELIVERED\n  FAILED\n  CANCELLED\n}\n\nenum NotificationTrigger {\n  MANUAL\n  AUTOMATIC\n}\n\nenum AutomationTrigger {\n  FORM_ASSIGNED\n  MISSING_DOCUMENTS\n  DOCUMENT_EXPIRING\n  DOCUMENT_EXPIRED\n  DOCUMENT_REJECTED\n  DOCUMENT_APPROVED\n}\n\nenum EmailIntegrationProvider {\n  IMAP\n  GMAIL\n  MICROSOFT_GRAPH\n}\n\nenum EmailIntegrationStatus {\n  DISCONNECTED\n  CONNECTED\n  ERROR\n  NEEDS_REAUTH\n}\n\nenum ProcessedEmailStatus {\n  RECEIVED\n  PROCESSING\n  PROCESSED\n  IGNORED\n  FAILED\n}\n\nenum EmailAttachmentStatus {\n  PENDING\n  EXTRACTING\n  EXTRACTED\n  MATCHED\n  NEEDS_REVIEW\n  UNMATCHED\n  DUPLICATE\n  FAILED\n  IGNORED\n}\n\nenum TextExtractionMethod {\n  NONE\n  TEXT_LAYER\n  OCR\n}\n\nenum ActorType {\n  USER\n  CLIENT_USER\n  SYSTEM\n}\n\n/// BullMQ queues (Redis). One queue per kind of work so each can have its own concurrency,\n/// rate limit and retry policy. Names match the registered queue names in the API.\nenum JobQueue {\n  NOTIFICATIONS\n  REMINDERS\n  EXPIRATION\n  EMAIL_SYNC\n  EMAIL_PROCESSING\n  DOCUMENT_PROCESSING\n  EXPORTS\n  MAINTENANCE\n}\n\n/// Mirrors the BullMQ job lifecycle. Every state change is written to job_runs.\nenum JobRunStatus {\n  QUEUED\n  DELAYED\n  ACTIVE\n  COMPLETED\n  FAILED\n  RETRYING\n  STALLED\n  CANCELLED\n}\n\n/// What put the job on the queue.\nenum JobTrigger {\n  SCHEDULER\n  API_REQUEST\n  WEBHOOK\n  JOB\n  MANUAL_RETRY\n  SYSTEM\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Accounts, sessions & tokens\n// ───────────────────────────────────────────────────────────────────────────────\n\n/// One account for everyone: workspace members, owners and portal clients.\n/// Workspace access comes from OrganizationMember rows; portal access from ClientUser rows.\nmodel User {\n  id                String    @id @default(uuid()) @db.Uuid\n  email             String    @unique\n  phone             String?   @unique\n  password          String\n  first_name        String?\n  last_name         String?\n  avatar_url        String?\n  language          String    @default(\"en\")\n  /// ISO 3166-1 alpha-2 country code chosen at sign-up, e.g. \"GR\".\n  country           String?\n  role              AuthRole  @default(USER)\n  email_verified_at DateTime?\n  last_login_at     DateTime?\n  created_at        DateTime  @default(now())\n  updated_at        DateTime  @updatedAt\n  deleted_at        DateTime?\n\n  password_reset_tokens     PasswordResetToken[]\n  email_verification_tokens EmailVerificationToken[]\n  sessions                  Session[]\n  memberships               OrganizationMember[]\n  client_users              ClientUser[]\n\n  organizations_created        Organization[]          @relation(\"OrganizationCreatedBy\")\n  invitations_sent             Invitation[]            @relation(\"InvitationInvitedBy\")\n  invitations_accepted         Invitation[]            @relation(\"InvitationAcceptedBy\")\n  clients_created              Client[]                @relation(\"ClientCreatedBy\")\n  client_assignments_made      ClientAssignment[]      @relation(\"ClientAssignmentAssignedBy\")\n  client_notes                 ClientNote[]            @relation(\"ClientNoteAuthor\")\n  forms_created                Form[]                  @relation(\"FormCreatedBy\")\n  form_versions_created        FormVersion[]           @relation(\"FormVersionCreatedBy\")\n  form_assignments_made        FormAssignment[]        @relation(\"FormAssignmentAssignedBy\")\n  form_responses_submitted     FormResponse[]          @relation(\"FormResponseSubmittedByUser\")\n  form_answers_updated         FormAnswer[]            @relation(\"FormAnswerUpdatedByUser\")\n  requirements_marked          AssignmentRequirement[] @relation(\"AssignmentRequirementNotRequiredBy\")\n  documents_uploaded           Document[]              @relation(\"DocumentUploadedByUser\")\n  documents_reviewed           Document[]              @relation(\"DocumentReviewedBy\")\n  document_versions_changed    DocumentVersion[]       @relation(\"DocumentVersionChangedByUser\")\n  inbox_items_reviewed         DocumentInboxItem[]     @relation(\"InboxItemReviewedBy\")\n  public_submissions_reviewed  PublicSubmission[]      @relation(\"PublicSubmissionReviewedBy\")\n  notifications_sent           Notification[]          @relation(\"NotificationSentBy\")\n  email_integrations_connected EmailIntegration[]      @relation(\"EmailIntegrationConnectedBy\")\n  activity_logs                ActivityLog[]           @relation(\"ActivityLogActorUser\")\n  job_runs_triggered           JobRun[]                @relation(\"JobRunTriggeredBy\")\n\n  @@index([email])\n  @@index([phone])\n  @@map(\"users\")\n}\n\nmodel PasswordResetToken {\n  id         String    @id @default(uuid()) @db.Uuid\n  token_hash String    @unique\n  user_uuid  String    @db.Uuid\n  expires_at DateTime\n  used_at    DateTime?\n  created_at DateTime  @default(now())\n\n  user User @relation(fields: [user_uuid], references: [id], onDelete: Cascade)\n\n  @@index([user_uuid])\n  @@index([expires_at])\n  @@map(\"password_reset_tokens\")\n}\n\nmodel EmailVerificationToken {\n  id         String    @id @default(uuid()) @db.Uuid\n  token_hash String    @unique\n  user_id    String    @db.Uuid\n  email      String\n  expires_at DateTime\n  used_at    DateTime?\n  created_at DateTime  @default(now())\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id])\n  @@index([expires_at])\n  @@map(\"email_verification_tokens\")\n}\n\n/// Server-side session record (refresh-token hash). A WORKSPACE session is bound to an\n/// organization; a PORTAL session is bound to a ClientUser. Revoking is explicit.\nmodel Session {\n  id              String      @id @default(uuid()) @db.Uuid\n  user_id         String      @db.Uuid\n  kind            SessionKind\n  organization_id String?     @db.Uuid\n  client_user_id  String?     @db.Uuid\n  token_hash      String      @unique\n  ip_address      String?\n  user_agent      String?\n  expires_at      DateTime\n  last_used_at    DateTime?\n  revoked_at      DateTime?\n  created_at      DateTime    @default(now())\n\n  user         User          @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  organization Organization? @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  client_user  ClientUser?   @relation(fields: [client_user_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id, kind])\n  @@index([organization_id])\n  @@index([client_user_id])\n  @@index([expires_at])\n  @@map(\"sessions\")\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Organizations, membership & invitations\n// ───────────────────────────────────────────────────────────────────────────────\n\nmodel Organization {\n  id                  String    @id @default(uuid()) @db.Uuid\n  name                String\n  slug                String    @unique\n  logo_storage_key    String?\n  logo_url            String?\n  contact_email       String?\n  contact_phone       String?\n  address             String?\n  time_zone           String    @default(\"Europe/Athens\")\n  default_language    String    @default(\"en\")\n  /// Plan allowance for File Space (\"2.4 GB of 50 GB included\"). Enforced in the API.\n  storage_limit_bytes BigInt    @default(53687091200)\n  created_by_user_id  String?   @db.Uuid\n  created_at          DateTime  @default(now())\n  updated_at          DateTime  @updatedAt\n  deleted_at          DateTime?\n\n  created_by User? @relation(\"OrganizationCreatedBy\", fields: [created_by_user_id], references: [id], onDelete: SetNull)\n\n  portal_settings       OrganizationPortalSettings?\n  document_settings     OrganizationDocumentSettings?\n  notification_settings NotificationSettings?\n\n  members                 OrganizationMember[]\n  invitations             Invitation[]\n  sessions                Session[]\n  clients                 Client[]\n  client_users            ClientUser[]\n  client_assignments      ClientAssignment[]\n  client_notes            ClientNote[]\n  forms                   Form[]\n  form_versions           FormVersion[]\n  document_requirements   DocumentRequirement[]\n  form_assignments        FormAssignment[]\n  assignment_requirements AssignmentRequirement[]\n  form_responses          FormResponse[]\n  form_answers            FormAnswer[]\n  documents               Document[]\n  document_versions       DocumentVersion[]\n  inbox_items             DocumentInboxItem[]\n  public_submissions      PublicSubmission[]\n  reminder_schedules      ReminderSchedule[]\n  notifications           Notification[]\n  notification_templates  NotificationTemplate[]\n  automation_rules        AutomationRule[]\n  email_integrations      EmailIntegration[]\n  processed_emails        ProcessedEmail[]\n  email_attachments       EmailAttachment[]\n  activity_logs           ActivityLog[]\n  job_runs                JobRun[]\n\n  @@index([slug])\n  @@index([deleted_at])\n  @@map(\"organizations\")\n}\n\n/// Settings > Client Portal.\nmodel OrganizationPortalSettings {\n  id                         String           @id @default(uuid()) @db.Uuid\n  organization_id            String           @unique @db.Uuid\n  access_mode                PortalAccessMode @default(PRIVATE)\n  /// Unguessable slug used in the public portal link (only meaningful when access_mode = PUBLIC).\n  public_slug                String?          @unique\n  welcome_message            String?\n  accent_color               String?          @db.VarChar(16)\n  invitation_validity_days   Int              @default(7)\n  invite_on_first_assignment Boolean          @default(true)\n  require_email_verification Boolean          @default(true)\n  created_at                 DateTime         @default(now())\n  updated_at                 DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"organization_portal_settings\")\n}\n\n/// Settings > Document Settings (plus per-organization matching thresholds for email processing).\nmodel OrganizationDocumentSettings {\n  id                          String           @id @default(uuid()) @db.Uuid\n  organization_id             String           @unique @db.Uuid\n  default_max_upload_mb       Int              @default(10)\n  accepted_formats            FileFormat[]     @default([PDF, IMAGE, WORD, EXCEL])\n  default_expiration_policy   ExpirationPolicy @default(MANUAL)\n  default_expiration_days     Int?\n  require_approval_by_default Boolean          @default(true)\n  /// Score at or above which an email match may be attached automatically (spec default 0.90).\n  match_high_threshold        Decimal          @default(0.90) @db.Decimal(4, 3)\n  /// Score at or above which an email match becomes a suggestion for review (spec default 0.60).\n  match_medium_threshold      Decimal          @default(0.60) @db.Decimal(4, 3)\n  created_at                  DateTime         @default(now())\n  updated_at                  DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  @@map(\"organization_document_settings\")\n}\n\nmodel OrganizationMember {\n  id              String           @id @default(uuid()) @db.Uuid\n  organization_id String           @db.Uuid\n  user_id         String           @db.Uuid\n  role            OrganizationRole @default(MEMBER)\n  status          MembershipStatus @default(ACTIVE)\n  joined_at       DateTime         @default(now())\n  last_active_at  DateTime?\n  removed_at      DateTime?\n  created_at      DateTime         @default(now())\n  updated_at      DateTime         @updatedAt\n\n  organization       Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  user               User               @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  client_assignments ClientAssignment[]\n\n  @@unique([organization_id, user_id])\n  @@index([organization_id, role])\n  @@index([user_id])\n  @@map(\"organization_members\")\n}\n\n/// Team and client invitations share one table; both land on the single sign-in page.\nmodel Invitation {\n  id                  String            @id @default(uuid()) @db.Uuid\n  organization_id     String            @db.Uuid\n  type                InvitationType\n  email               String\n  /// TEAM invitations only.\n  role                OrganizationRole?\n  /// CLIENT invitations only.\n  client_id           String?           @db.Uuid\n  token_hash          String            @unique\n  status              InvitationStatus  @default(PENDING)\n  message             String?\n  invited_by_user_id  String?           @db.Uuid\n  accepted_by_user_id String?           @db.Uuid\n  expires_at          DateTime\n  accepted_at         DateTime?\n  revoked_at          DateTime?\n  last_sent_at        DateTime?\n  send_count          Int               @default(1)\n  created_at          DateTime          @default(now())\n  updated_at          DateTime          @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  client       Client?      @relation(fields: [client_id], references: [id], onDelete: Cascade)\n  invited_by   User?        @relation(\"InvitationInvitedBy\", fields: [invited_by_user_id], references: [id], onDelete: SetNull)\n  accepted_by  User?        @relation(\"InvitationAcceptedBy\", fields: [accepted_by_user_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, type, status])\n  @@index([email])\n  @@index([client_id])\n  @@index([expires_at])\n  @@map(\"invitations\")\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Clients & client portal accounts\n// ───────────────────────────────────────────────────────────────────────────────\n\nmodel Client {\n  id                 String       @id @default(uuid()) @db.Uuid\n  organization_id    String       @db.Uuid\n  first_name         String\n  last_name          String\n  company            String?\n  email              String?\n  phone              String?\n  tax_id             String?\n  /// ISO 3166-1 alpha-2 country code, e.g. \"GR\".\n  country            String?\n  address            String?\n  /// Free-text company information shown on the Overview tab (\"Company notes\").\n  company_info       String?\n  status             ClientStatus @default(ACTIVE)\n  created_by_user_id String?      @db.Uuid\n  archived_at        DateTime?\n  created_at         DateTime     @default(now())\n  updated_at         DateTime     @updatedAt\n  deleted_at         DateTime?\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  created_by   User?        @relation(\"ClientCreatedBy\", fields: [created_by_user_id], references: [id], onDelete: SetNull)\n\n  client_users             ClientUser[]\n  invitations              Invitation[]\n  assignees                ClientAssignment[]\n  notes                    ClientNote[]\n  form_assignments         FormAssignment[]\n  documents                Document[]\n  inbox_items_detected     DocumentInboxItem[] @relation(\"InboxItemDetectedClient\")\n  inbox_items_resolved     DocumentInboxItem[] @relation(\"InboxItemResolvedClient\")\n  public_submissions       PublicSubmission[]  @relation(\"PublicSubmissionResolvedClient\")\n  notifications            Notification[]\n  processed_emails_matched ProcessedEmail[]    @relation(\"ProcessedEmailMatchedClient\")\n  activity_logs            ActivityLog[]\n\n  @@index([organization_id, status])\n  @@index([organization_id, last_name, first_name])\n  @@index([organization_id, company])\n  @@index([organization_id, email])\n  @@index([organization_id, tax_id])\n  @@index([organization_id, created_at])\n  @@map(\"clients\")\n}\n\n/// Many-to-many: clients ↔ assigned employees (organization members).\nmodel ClientAssignment {\n  id                     String   @id @default(uuid()) @db.Uuid\n  organization_id        String   @db.Uuid\n  client_id              String   @db.Uuid\n  organization_member_id String   @db.Uuid\n  assigned_by_user_id    String?  @db.Uuid\n  created_at             DateTime @default(now())\n\n  organization Organization       @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  client       Client             @relation(fields: [client_id], references: [id], onDelete: Cascade)\n  member       OrganizationMember @relation(fields: [organization_member_id], references: [id], onDelete: Cascade)\n  assigned_by  User?              @relation(\"ClientAssignmentAssignedBy\", fields: [assigned_by_user_id], references: [id], onDelete: SetNull)\n\n  @@unique([client_id, organization_member_id])\n  @@index([organization_id, organization_member_id])\n  @@map(\"client_assignments\")\n}\n\n/// Portal account for one client of one organization. `user_id` is set once the invitation is\n/// activated (the same User can be a client of several organizations and a member of others).\nmodel ClientUser {\n  id                    String           @id @default(uuid()) @db.Uuid\n  organization_id       String           @db.Uuid\n  client_id             String           @db.Uuid\n  user_id               String?          @db.Uuid\n  email                 String\n  status                ClientUserStatus @default(INVITED)\n  invited_at            DateTime?\n  activated_at          DateTime?\n  last_login_at         DateTime?\n  disabled_at           DateTime?\n  /// Portal > Account Settings > Email notifications.\n  notify_reminders      Boolean          @default(true)\n  notify_review_updates Boolean          @default(true)\n  created_at            DateTime         @default(now())\n  updated_at            DateTime         @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  client       Client       @relation(fields: [client_id], references: [id], onDelete: Cascade)\n  user         User?        @relation(fields: [user_id], references: [id], onDelete: SetNull)\n\n  sessions                  Session[]\n  form_responses_submitted  FormResponse[]    @relation(\"FormResponseSubmittedByClientUser\")\n  form_answers_updated      FormAnswer[]      @relation(\"FormAnswerUpdatedByClientUser\")\n  documents_uploaded        Document[]        @relation(\"DocumentUploadedByClientUser\")\n  document_versions_changed DocumentVersion[] @relation(\"DocumentVersionChangedByClientUser\")\n  notifications             Notification[]\n  activity_logs             ActivityLog[]     @relation(\"ActivityLogActorClientUser\")\n\n  @@unique([client_id, email])\n  @@unique([client_id, user_id])\n  @@index([organization_id, status])\n  @@index([user_id])\n  @@map(\"client_users\")\n}\n\n/// Internal notes (Client details > Notes). Visible to employees only.\nmodel ClientNote {\n  id              String    @id @default(uuid()) @db.Uuid\n  organization_id String    @db.Uuid\n  client_id       String    @db.Uuid\n  author_user_id  String?   @db.Uuid\n  body            String\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n  deleted_at      DateTime?\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  client       Client       @relation(fields: [client_id], references: [id], onDelete: Cascade)\n  author       User?        @relation(\"ClientNoteAuthor\", fields: [author_user_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, client_id, created_at])\n  @@map(\"client_notes\")\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Forms, versions & document requirements\n// ───────────────────────────────────────────────────────────────────────────────\n\n/// Reusable form (the thing listed on Forms & Templates). Content lives in versions.\nmodel Form {\n  id                 String     @id @default(uuid()) @db.Uuid\n  organization_id    String     @db.Uuid\n  name               String\n  description        String?\n  status             FormStatus @default(DRAFT)\n  is_template        Boolean    @default(false)\n  /// Can be opened and submitted through the public portal (access_mode = PUBLIC).\n  is_public          Boolean    @default(false)\n  /// Latest version (draft or published). The UI always edits/shows this one.\n  current_version_id String?    @unique @db.Uuid\n  /// Set when this form was created by duplicating another form.\n  duplicated_from_id String?    @db.Uuid\n  created_by_user_id String?    @db.Uuid\n  archived_at        DateTime?\n  created_at         DateTime   @default(now())\n  updated_at         DateTime   @updatedAt\n  deleted_at         DateTime?\n\n  organization    Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  created_by      User?        @relation(\"FormCreatedBy\", fields: [created_by_user_id], references: [id], onDelete: SetNull)\n  current_version FormVersion? @relation(\"FormCurrentVersion\", fields: [current_version_id], references: [id], onDelete: SetNull)\n  duplicated_from Form?        @relation(\"FormDuplicatedFrom\", fields: [duplicated_from_id], references: [id], onDelete: SetNull)\n  duplicates      Form[]       @relation(\"FormDuplicatedFrom\")\n\n  versions           FormVersion[]      @relation(\"FormVersions\")\n  assignments        FormAssignment[]\n  public_submissions PublicSubmission[]\n  automation_rules   AutomationRule[]\n\n  @@index([organization_id, status])\n  @@index([organization_id, is_template])\n  @@index([organization_id, name])\n  @@map(\"forms\")\n}\n\n/// Immutable once published. Saving an edited published form creates the next version.\n/// `definition` is the structured JSON schema: sections → fields (type, label, help, required,\n/// default, validation, options, conditional visibility, file-upload config). Publishing a version\n/// generates its DocumentRequirement rows from the FILE_UPLOAD fields.\nmodel FormVersion {\n  id                            String            @id @default(uuid()) @db.Uuid\n  organization_id               String            @db.Uuid\n  form_id                       String            @db.Uuid\n  version_number                Int\n  status                        FormVersionStatus @default(DRAFT)\n  title                         String\n  description                   String?\n  instructions                  String?\n  definition                    Json\n  /// Form-level default expiration policy for documents collected through this version.\n  default_expiration_policy     ExpirationPolicy  @default(MANUAL)\n  default_expiration_days       Int?\n  default_fixed_expiration_date DateTime?         @db.Date\n  /// Form-level default reminder schedule (falls through to the organization default).\n  default_reminder_schedule_id  String?           @db.Uuid\n  field_count                   Int               @default(0)\n  document_count                Int               @default(0)\n  created_by_user_id            String?           @db.Uuid\n  published_at                  DateTime?\n  created_at                    DateTime          @default(now())\n  updated_at                    DateTime          @updatedAt\n\n  organization              Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  form                      Form              @relation(\"FormVersions\", fields: [form_id], references: [id], onDelete: Cascade)\n  created_by                User?             @relation(\"FormVersionCreatedBy\", fields: [created_by_user_id], references: [id], onDelete: SetNull)\n  default_reminder_schedule ReminderSchedule? @relation(\"FormVersionReminderSchedule\", fields: [default_reminder_schedule_id], references: [id], onDelete: SetNull)\n\n  current_of_form       Form?                 @relation(\"FormCurrentVersion\")\n  document_requirements DocumentRequirement[]\n  assignments           FormAssignment[]\n  public_submissions    PublicSubmission[]\n\n  @@unique([form_id, version_number])\n  @@index([organization_id, form_id, status])\n  @@map(\"form_versions\")\n}\n\n/// Expected document defined by a FILE_UPLOAD field of a form version (what is expected).\nmodel DocumentRequirement {\n  id                         String           @id @default(uuid()) @db.Uuid\n  organization_id            String           @db.Uuid\n  form_version_id            String           @db.Uuid\n  /// The FILE_UPLOAD field id inside FormVersion.definition.\n  field_key                  String\n  name                       String\n  description                String?\n  instructions               String?\n  is_required                Boolean          @default(true)\n  sort_order                 Int              @default(0)\n  accepted_formats           FileFormat[]     @default([PDF, IMAGE])\n  max_file_size_mb           Int              @default(10)\n  max_files                  Int              @default(1)\n  allow_multiple_submissions Boolean          @default(false)\n  requires_approval          Boolean          @default(true)\n  expiration_policy          ExpirationPolicy @default(MANUAL)\n  expiration_days            Int?\n  fixed_expiration_date      DateTime?        @db.Date\n  /// Document-level reminder schedule (overrides the form default when set).\n  reminder_schedule_id       String?          @db.Uuid\n  created_at                 DateTime         @default(now())\n\n  organization      Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  form_version      FormVersion       @relation(fields: [form_version_id], references: [id], onDelete: Cascade)\n  reminder_schedule ReminderSchedule? @relation(\"DocumentRequirementReminderSchedule\", fields: [reminder_schedule_id], references: [id], onDelete: SetNull)\n\n  assignment_requirements AssignmentRequirement[]\n  documents               Document[]\n\n  @@unique([form_version_id, field_key])\n  @@index([organization_id])\n  @@map(\"document_requirements\")\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Assignments, requirements & responses\n// ───────────────────────────────────────────────────────────────────────────────\n\n/// A form (pinned to a version) assigned to a client.\nmodel FormAssignment {\n  id                     String           @id @default(uuid()) @db.Uuid\n  organization_id        String           @db.Uuid\n  client_id              String           @db.Uuid\n  form_id                String           @db.Uuid\n  form_version_id        String           @db.Uuid\n  assigned_by_user_id    String?          @db.Uuid\n  assigned_at            DateTime         @default(now())\n  deadline               DateTime?\n  /// Assignment-level reminder schedule override (whole assignment).\n  reminder_schedule_id   String?          @db.Uuid\n  message                String?\n  status                 AssignmentStatus @default(NOT_STARTED)\n  /// Cached progress, recomputed whenever a requirement changes.\n  requirements_total     Int              @default(0)\n  requirements_completed Int              @default(0)\n  requirements_missing   Int              @default(0)\n  requirements_expired   Int              @default(0)\n  progress_percent       Int              @default(0)\n  last_submission_at     DateTime?\n  completed_at           DateTime?\n  cancelled_at           DateTime?\n  created_at             DateTime         @default(now())\n  updated_at             DateTime         @updatedAt\n\n  organization      Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  client            Client            @relation(fields: [client_id], references: [id], onDelete: Cascade)\n  form              Form              @relation(fields: [form_id], references: [id], onDelete: Restrict)\n  form_version      FormVersion       @relation(fields: [form_version_id], references: [id], onDelete: Restrict)\n  assigned_by       User?             @relation(\"FormAssignmentAssignedBy\", fields: [assigned_by_user_id], references: [id], onDelete: SetNull)\n  reminder_schedule ReminderSchedule? @relation(\"FormAssignmentReminderSchedule\", fields: [reminder_schedule_id], references: [id], onDelete: SetNull)\n\n  requirements          AssignmentRequirement[]\n  response              FormResponse?\n  documents             Document[]\n  inbox_items_suggested DocumentInboxItem[]     @relation(\"InboxItemSuggestedAssignment\")\n  inbox_items_resolved  DocumentInboxItem[]     @relation(\"InboxItemResolvedAssignment\")\n  public_submissions    PublicSubmission[]      @relation(\"PublicSubmissionResolvedAssignment\")\n  notifications         Notification[]\n  activity_logs         ActivityLog[]\n\n  @@index([organization_id, status])\n  @@index([organization_id, client_id])\n  @@index([organization_id, form_id])\n  @@index([organization_id, deadline])\n  @@index([form_version_id])\n  @@map(\"form_assignments\")\n}\n\n/// A document requirement as it lives inside one assignment (per-requirement deadline,\n/// reminder override, cached effective status, pointer to the current submission).\nmodel AssignmentRequirement {\n  id                           String            @id @default(uuid()) @db.Uuid\n  organization_id              String            @db.Uuid\n  assignment_id                String            @db.Uuid\n  document_requirement_id      String            @db.Uuid\n  status                       RequirementStatus @default(MISSING)\n  /// Own deadline; null falls back to the assignment deadline.\n  deadline                     DateTime?\n  /// Per-requirement reminder schedule override.\n  reminder_schedule_id         String?           @db.Uuid\n  /// Latest relevant submission the status is derived from.\n  current_document_id          String?           @unique @db.Uuid\n  not_required_reason          String?\n  not_required_by_user_id      String?           @db.Uuid\n  not_required_at              DateTime?\n  reminders_sent_count         Int               @default(0)\n  overdue_reminders_sent_count Int               @default(0)\n  last_reminder_sent_at        DateTime?\n  next_reminder_at             DateTime?\n  created_at                   DateTime          @default(now())\n  updated_at                   DateTime          @updatedAt\n\n  organization         Organization        @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  assignment           FormAssignment      @relation(fields: [assignment_id], references: [id], onDelete: Cascade)\n  document_requirement DocumentRequirement @relation(fields: [document_requirement_id], references: [id], onDelete: Restrict)\n  reminder_schedule    ReminderSchedule?   @relation(\"AssignmentRequirementReminderSchedule\", fields: [reminder_schedule_id], references: [id], onDelete: SetNull)\n  current_document     Document?           @relation(\"RequirementCurrentDocument\", fields: [current_document_id], references: [id], onDelete: SetNull)\n  not_required_by      User?               @relation(\"AssignmentRequirementNotRequiredBy\", fields: [not_required_by_user_id], references: [id], onDelete: SetNull)\n\n  documents             Document[]          @relation(\"RequirementDocuments\")\n  inbox_items_suggested DocumentInboxItem[] @relation(\"InboxItemSuggestedRequirement\")\n  inbox_items_resolved  DocumentInboxItem[] @relation(\"InboxItemResolvedRequirement\")\n\n  @@unique([assignment_id, document_requirement_id])\n  @@index([organization_id, status])\n  @@index([organization_id, next_reminder_at])\n  @@index([document_requirement_id])\n  @@map(\"assignment_requirements\")\n}\n\n/// The non-file answers of one assignment (one response per assignment; drafts allowed).\nmodel FormResponse {\n  id                          String             @id @default(uuid()) @db.Uuid\n  organization_id             String             @db.Uuid\n  assignment_id               String             @unique @db.Uuid\n  status                      FormResponseStatus @default(DRAFT)\n  submitted_at                DateTime?\n  submitted_by_user_id        String?            @db.Uuid\n  submitted_by_client_user_id String?            @db.Uuid\n  last_saved_at               DateTime?\n  created_at                  DateTime           @default(now())\n  updated_at                  DateTime           @updatedAt\n\n  organization             Organization   @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  assignment               FormAssignment @relation(fields: [assignment_id], references: [id], onDelete: Cascade)\n  submitted_by_user        User?          @relation(\"FormResponseSubmittedByUser\", fields: [submitted_by_user_id], references: [id], onDelete: SetNull)\n  submitted_by_client_user ClientUser?    @relation(\"FormResponseSubmittedByClientUser\", fields: [submitted_by_client_user_id], references: [id], onDelete: SetNull)\n\n  answers FormAnswer[]\n\n  @@index([organization_id, status])\n  @@map(\"form_responses\")\n}\n\n/// One answer per field. `value` is JSON so every field type fits (string, number, boolean,\n/// ISO date, string[] for checkboxes). Edits are audited in activity_logs with before/after values.\nmodel FormAnswer {\n  id                        String        @id @default(uuid()) @db.Uuid\n  organization_id           String        @db.Uuid\n  response_id               String        @db.Uuid\n  field_key                 String\n  field_type                FormFieldType\n  value                     Json?\n  updated_by_user_id        String?       @db.Uuid\n  updated_by_client_user_id String?       @db.Uuid\n  created_at                DateTime      @default(now())\n  updated_at                DateTime      @updatedAt\n\n  organization           Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  response               FormResponse @relation(fields: [response_id], references: [id], onDelete: Cascade)\n  updated_by_user        User?        @relation(\"FormAnswerUpdatedByUser\", fields: [updated_by_user_id], references: [id], onDelete: SetNull)\n  updated_by_client_user ClientUser?  @relation(\"FormAnswerUpdatedByClientUser\", fields: [updated_by_client_user_id], references: [id], onDelete: SetNull)\n\n  @@unique([response_id, field_key])\n  @@index([organization_id])\n  @@map(\"form_answers\")\n}\n\n/// Anonymous submission made through the public portal. Marked unverified; an employee\n/// resolves it from the Document Inbox into a client + assignment.\nmodel PublicSubmission {\n  id                     String                 @id @default(uuid()) @db.Uuid\n  organization_id        String                 @db.Uuid\n  form_id                String                 @db.Uuid\n  form_version_id        String                 @db.Uuid\n  submitter_name         String?\n  submitter_email        String?\n  submitter_company      String?\n  answers                Json?\n  status                 PublicSubmissionStatus @default(PENDING_REVIEW)\n  ip_address             String?\n  resolved_client_id     String?                @db.Uuid\n  resolved_assignment_id String?                @db.Uuid\n  reviewed_by_user_id    String?                @db.Uuid\n  reviewed_at            DateTime?\n  review_note            String?\n  submitted_at           DateTime               @default(now())\n  created_at             DateTime               @default(now())\n  updated_at             DateTime               @updatedAt\n\n  organization        Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  form                Form            @relation(fields: [form_id], references: [id], onDelete: Cascade)\n  form_version        FormVersion     @relation(fields: [form_version_id], references: [id], onDelete: Restrict)\n  resolved_client     Client?         @relation(\"PublicSubmissionResolvedClient\", fields: [resolved_client_id], references: [id], onDelete: SetNull)\n  resolved_assignment FormAssignment? @relation(\"PublicSubmissionResolvedAssignment\", fields: [resolved_assignment_id], references: [id], onDelete: SetNull)\n  reviewed_by         User?           @relation(\"PublicSubmissionReviewedBy\", fields: [reviewed_by_user_id], references: [id], onDelete: SetNull)\n\n  documents   Document[]\n  inbox_items DocumentInboxItem[]\n\n  @@index([organization_id, status])\n  @@index([organization_id, form_id])\n  @@map(\"public_submissions\")\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Documents (what was actually received)\n// ───────────────────────────────────────────────────────────────────────────────\n\n/// One uploaded file = one submission. Replacing a document creates a new row that supersedes\n/// the previous one; earlier rows are preserved. Current lifecycle status is derived on the\n/// requirement from review_status + expiration_date + supersession.\nmodel Document {\n  id                         String            @id @default(uuid()) @db.Uuid\n  organization_id            String            @db.Uuid\n  client_id                  String?           @db.Uuid\n  assignment_id              String?           @db.Uuid\n  assignment_requirement_id  String?           @db.Uuid\n  /// Denormalized from the assignment requirement for cross-client \"document type\" filtering.\n  document_requirement_id    String?           @db.Uuid\n  public_submission_id       String?           @db.Uuid\n  /// Display name / document type (defaults to the requirement name).\n  title                      String\n  original_filename          String\n  storage_key                String            @unique\n  storage_bucket             String?\n  mime_type                  String\n  file_format                FileFormat\n  size_bytes                 Int\n  checksum_sha256            String?\n  source                     UploadSource\n  uploaded_by_user_id        String?           @db.Uuid\n  uploaded_by_client_user_id String?           @db.Uuid\n  uploaded_at                DateTime          @default(now())\n  expiration_date            DateTime?         @db.Date\n  expiration_source          ExpirationSource?\n  expiration_verified_at     DateTime?\n  review_status              ReviewStatus      @default(PENDING)\n  reviewed_by_user_id        String?           @db.Uuid\n  reviewed_at                DateTime?\n  rejection_reason           String?\n  /// Set when a later submission replaced this one.\n  superseded_by_id           String?           @unique @db.Uuid\n  superseded_at              DateTime?\n  /// Public-portal uploads stay unverified until an employee resolves them.\n  is_verified                Boolean           @default(true)\n  notes                      String?\n  metadata                   Json?\n  created_at                 DateTime          @default(now())\n  updated_at                 DateTime          @updatedAt\n  deleted_at                 DateTime?\n\n  organization            Organization           @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  client                  Client?                @relation(fields: [client_id], references: [id], onDelete: Cascade)\n  assignment              FormAssignment?        @relation(fields: [assignment_id], references: [id], onDelete: SetNull)\n  assignment_requirement  AssignmentRequirement? @relation(\"RequirementDocuments\", fields: [assignment_requirement_id], references: [id], onDelete: SetNull)\n  document_requirement    DocumentRequirement?   @relation(fields: [document_requirement_id], references: [id], onDelete: SetNull)\n  public_submission       PublicSubmission?      @relation(fields: [public_submission_id], references: [id], onDelete: SetNull)\n  uploaded_by_user        User?                  @relation(\"DocumentUploadedByUser\", fields: [uploaded_by_user_id], references: [id], onDelete: SetNull)\n  uploaded_by_client_user ClientUser?            @relation(\"DocumentUploadedByClientUser\", fields: [uploaded_by_client_user_id], references: [id], onDelete: SetNull)\n  reviewed_by             User?                  @relation(\"DocumentReviewedBy\", fields: [reviewed_by_user_id], references: [id], onDelete: SetNull)\n  superseded_by           Document?              @relation(\"DocumentSupersession\", fields: [superseded_by_id], references: [id], onDelete: SetNull)\n  supersedes              Document?              @relation(\"DocumentSupersession\")\n\n  current_for_requirement AssignmentRequirement? @relation(\"RequirementCurrentDocument\")\n  versions                DocumentVersion[]\n  inbox_items             DocumentInboxItem[]\n  email_attachment        EmailAttachment?\n  activity_logs           ActivityLog[]\n\n  @@index([organization_id, client_id])\n  @@index([organization_id, assignment_id])\n  @@index([organization_id, assignment_requirement_id])\n  @@index([organization_id, document_requirement_id])\n  @@index([organization_id, review_status])\n  @@index([organization_id, expiration_date])\n  @@index([organization_id, uploaded_at])\n  @@index([organization_id, file_format])\n  @@index([organization_id, checksum_sha256])\n  @@map(\"documents\")\n}\n\n/// History of changes made to a single document record (file, metadata, expiration, review).\nmodel DocumentVersion {\n  id                        String                    @id @default(uuid()) @db.Uuid\n  organization_id           String                    @db.Uuid\n  document_id               String                    @db.Uuid\n  version_number            Int\n  change_type               DocumentVersionChangeType\n  /// Snapshot of the record after the change.\n  original_filename         String\n  storage_key               String\n  mime_type                 String\n  size_bytes                Int\n  expiration_date           DateTime?                 @db.Date\n  review_status             ReviewStatus\n  snapshot                  Json?\n  change_reason             String?\n  changed_by_user_id        String?                   @db.Uuid\n  changed_by_client_user_id String?                   @db.Uuid\n  created_at                DateTime                  @default(now())\n\n  organization           Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  document               Document     @relation(fields: [document_id], references: [id], onDelete: Cascade)\n  changed_by_user        User?        @relation(\"DocumentVersionChangedByUser\", fields: [changed_by_user_id], references: [id], onDelete: SetNull)\n  changed_by_client_user ClientUser?  @relation(\"DocumentVersionChangedByClientUser\", fields: [changed_by_client_user_id], references: [id], onDelete: SetNull)\n\n  @@unique([document_id, version_number])\n  @@index([organization_id])\n  @@map(\"document_versions\")\n}\n\n/// Centralized Document Inbox entry. Every incoming file (portal, employee, public portal, email)\n/// gets one. Portal/employee uploads arrive HIGH + MATCHED and need review only when the\n/// requirement requires approval.\nmodel DocumentInboxItem {\n  id                       String                @id @default(uuid()) @db.Uuid\n  organization_id          String                @db.Uuid\n  source                   UploadSource\n  processing_status        InboxProcessingStatus @default(RECEIVED)\n  /// True while the item sits in the \"Needs review\" list (drives the navigation badge).\n  needs_review             Boolean               @default(false)\n  requires_approval        Boolean               @default(false)\n  is_verified              Boolean               @default(true)\n  detected_client_id       String?               @db.Uuid\n  detected_document_type   String?\n  suggested_assignment_id  String?               @db.Uuid\n  suggested_requirement_id String?               @db.Uuid\n  confidence               MatchConfidence?\n  confidence_score         Decimal?              @db.Decimal(4, 3)\n  /// Signals that produced the score, e.g. [{ \"signal\": \"sender_email_exact\", \"weight\": 0.5 }].\n  match_signals            Json?\n  /// Set when more than one client could match (never auto-attach).\n  is_ambiguous             Boolean               @default(false)\n  document_id              String?               @db.Uuid\n  email_attachment_id      String?               @unique @db.Uuid\n  public_submission_id     String?               @db.Uuid\n  review_action            InboxReviewAction?\n  resolved_client_id       String?               @db.Uuid\n  resolved_assignment_id   String?               @db.Uuid\n  resolved_requirement_id  String?               @db.Uuid\n  reviewed_by_user_id      String?               @db.Uuid\n  reviewed_at              DateTime?\n  review_note              String?\n  failure_reason           String?\n  received_at              DateTime              @default(now())\n  created_at               DateTime              @default(now())\n  updated_at               DateTime              @updatedAt\n\n  organization          Organization           @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  detected_client       Client?                @relation(\"InboxItemDetectedClient\", fields: [detected_client_id], references: [id], onDelete: SetNull)\n  suggested_assignment  FormAssignment?        @relation(\"InboxItemSuggestedAssignment\", fields: [suggested_assignment_id], references: [id], onDelete: SetNull)\n  suggested_requirement AssignmentRequirement? @relation(\"InboxItemSuggestedRequirement\", fields: [suggested_requirement_id], references: [id], onDelete: SetNull)\n  document              Document?              @relation(fields: [document_id], references: [id], onDelete: SetNull)\n  email_attachment      EmailAttachment?       @relation(fields: [email_attachment_id], references: [id], onDelete: SetNull)\n  public_submission     PublicSubmission?      @relation(fields: [public_submission_id], references: [id], onDelete: SetNull)\n  resolved_client       Client?                @relation(\"InboxItemResolvedClient\", fields: [resolved_client_id], references: [id], onDelete: SetNull)\n  resolved_assignment   FormAssignment?        @relation(\"InboxItemResolvedAssignment\", fields: [resolved_assignment_id], references: [id], onDelete: SetNull)\n  resolved_requirement  AssignmentRequirement? @relation(\"InboxItemResolvedRequirement\", fields: [resolved_requirement_id], references: [id], onDelete: SetNull)\n  reviewed_by           User?                  @relation(\"InboxItemReviewedBy\", fields: [reviewed_by_user_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, needs_review, received_at])\n  @@index([organization_id, processing_status])\n  @@index([organization_id, source])\n  @@index([organization_id, confidence])\n  @@index([organization_id, detected_client_id])\n  @@index([document_id])\n  @@map(\"document_inbox_items\")\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Reminders, notifications & automation\n// ───────────────────────────────────────────────────────────────────────────────\n\n/// Reusable reminder schedule. Referenced from the organization default (NotificationSettings),\n/// form versions, document requirements, assignments and assignment requirements. Null columns\n/// fall through to the next-lower precedence level; the organization default is fully populated.\nmodel ReminderSchedule {\n  id                       String                @id @default(uuid()) @db.Uuid\n  organization_id          String                @db.Uuid\n  enabled                  Boolean?\n  /// Days before the deadline reminders begin (0 = on the deadline day).\n  start_days_before        Int?\n  interval_count           Int?\n  interval_unit            ReminderIntervalUnit?\n  /// ISO weekday (1 = Monday … 7 = Sunday) reminders are sent on when the interval unit is WEEKS.\n  interval_weekday         Int?\n  /// Time of day in the organization time zone, \"HH:mm\".\n  send_time                String?               @db.VarChar(5)\n  overdue_enabled          Boolean?\n  overdue_interval_count   Int?\n  overdue_interval_unit    ReminderIntervalUnit?\n  overdue_interval_weekday Int?\n  overdue_max_count        Int?\n  created_at               DateTime              @default(now())\n  updated_at               DateTime              @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  notification_settings   NotificationSettings?\n  form_versions           FormVersion[]           @relation(\"FormVersionReminderSchedule\")\n  document_requirements   DocumentRequirement[]   @relation(\"DocumentRequirementReminderSchedule\")\n  form_assignments        FormAssignment[]        @relation(\"FormAssignmentReminderSchedule\")\n  assignment_requirements AssignmentRequirement[] @relation(\"AssignmentRequirementReminderSchedule\")\n\n  @@index([organization_id])\n  @@map(\"reminder_schedules\")\n}\n\n/// Settings > Notifications (organization level).\nmodel NotificationSettings {\n  id                           String                @id @default(uuid()) @db.Uuid\n  organization_id              String                @unique @db.Uuid\n  enabled_channels             NotificationChannel[] @default([EMAIL])\n  email_provider               EmailProvider         @default(RESEND)\n  sms_provider                 SmsProvider?\n  sender_name                  String?\n  sender_email                 String?\n  /// Phase 2.\n  sms_sender                   String?\n  auto_reminders_enabled       Boolean               @default(true)\n  default_reminder_schedule_id String?               @unique @db.Uuid\n  quiet_hours_start            String?               @db.VarChar(5)\n  quiet_hours_end              String?               @db.VarChar(5)\n  retry_max_attempts           Int                   @default(3)\n  retry_interval_minutes       Int                   @default(60)\n  created_at                   DateTime              @default(now())\n  updated_at                   DateTime              @updatedAt\n\n  organization              Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  default_reminder_schedule ReminderSchedule? @relation(fields: [default_reminder_schedule_id], references: [id], onDelete: SetNull)\n\n  @@map(\"notification_settings\")\n}\n\n/// Reusable message template with {{variables}}. Default templates are seeded per organization.\nmodel NotificationTemplate {\n  id              String              @id @default(uuid()) @db.Uuid\n  organization_id String              @db.Uuid\n  type            NotificationType\n  channel         NotificationChannel @default(EMAIL)\n  name            String\n  subject         String?\n  body            String\n  /// The template used by default for this type/channel.\n  is_default      Boolean             @default(false)\n  is_system       Boolean             @default(false)\n  created_at      DateTime            @default(now())\n  updated_at      DateTime            @updatedAt\n  deleted_at      DateTime?\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n\n  notifications    Notification[]\n  automation_rules AutomationRule[]\n\n  @@unique([organization_id, name])\n  @@index([organization_id, type, channel, is_default])\n  @@map(\"notification_templates\")\n}\n\n/// Automatic reminder configuration per trigger. `form_id` null = organization-wide rule;\n/// a form-scoped rule overrides it. Missing-document timing comes from ReminderSchedule;\n/// expiring/expired rules use the offsets and repeat settings here.\nmodel AutomationRule {\n  id                    String                @id @default(uuid()) @db.Uuid\n  organization_id       String                @db.Uuid\n  form_id               String?               @db.Uuid\n  name                  String\n  trigger               AutomationTrigger\n  enabled               Boolean               @default(true)\n  channels              NotificationChannel[] @default([EMAIL])\n  template_id           String?               @db.Uuid\n  /// DOCUMENT_EXPIRING: days before expiration to notify, e.g. [30, 7, 0].\n  offsets_days          Int[]                 @default([])\n  /// Repeat behaviour (DOCUMENT_EXPIRED keeps reminding until a replacement is approved).\n  repeat_enabled        Boolean               @default(false)\n  repeat_interval_count Int?\n  repeat_interval_unit  ReminderIntervalUnit?\n  max_sends             Int?\n  config                Json?\n  is_system             Boolean               @default(false)\n  created_at            DateTime              @default(now())\n  updated_at            DateTime              @updatedAt\n\n  organization Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  form         Form?                 @relation(fields: [form_id], references: [id], onDelete: Cascade)\n  template     NotificationTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n\n  notifications Notification[]\n\n  @@index([organization_id, trigger, enabled])\n  @@index([form_id])\n  @@map(\"automation_rules\")\n}\n\n/// Notification history (one row per message per recipient per channel).\nmodel Notification {\n  id                  String              @id @default(uuid()) @db.Uuid\n  organization_id     String              @db.Uuid\n  channel             NotificationChannel\n  type                NotificationType\n  trigger             NotificationTrigger @default(AUTOMATIC)\n  recipient_address   String\n  recipient_name      String?\n  client_id           String?             @db.Uuid\n  client_user_id      String?             @db.Uuid\n  assignment_id       String?             @db.Uuid\n  template_id         String?             @db.Uuid\n  automation_rule_id  String?             @db.Uuid\n  sent_by_user_id     String?             @db.Uuid\n  subject             String?\n  body                String\n  body_html           String?\n  /// Prevents duplicate sends, e.g. \"missing:<assignment_requirement_id>:<yyyy-mm-dd>:<HH:mm>\".\n  idempotency_key     String?             @unique\n  status              NotificationStatus  @default(PENDING)\n  provider            String?\n  provider_message_id String?\n  provider_response   Json?\n  failure_reason      String?\n  attempt_count       Int                 @default(0)\n  scheduled_for       DateTime?\n  next_retry_at       DateTime?\n  sent_at             DateTime?\n  delivered_at        DateTime?\n  failed_at           DateTime?\n  cancelled_at        DateTime?\n  /// Related requirement ids, document ids, etc.\n  metadata            Json?\n  created_at          DateTime            @default(now())\n  updated_at          DateTime            @updatedAt\n\n  organization    Organization          @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  client          Client?               @relation(fields: [client_id], references: [id], onDelete: SetNull)\n  client_user     ClientUser?           @relation(fields: [client_user_id], references: [id], onDelete: SetNull)\n  assignment      FormAssignment?       @relation(fields: [assignment_id], references: [id], onDelete: SetNull)\n  template        NotificationTemplate? @relation(fields: [template_id], references: [id], onDelete: SetNull)\n  automation_rule AutomationRule?       @relation(fields: [automation_rule_id], references: [id], onDelete: SetNull)\n  sent_by         User?                 @relation(\"NotificationSentBy\", fields: [sent_by_user_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, created_at])\n  @@index([organization_id, status])\n  @@index([organization_id, client_id])\n  @@index([organization_id, type])\n  @@index([status, next_retry_at])\n  @@index([provider_message_id])\n  @@map(\"notifications\")\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Email integrations & automatic email processing (Phase 2 surface, modelled now)\n// ───────────────────────────────────────────────────────────────────────────────\n\n/// A connected inbox. Secrets are stored encrypted (application-level encryption) and never\n/// returned to the frontend.\nmodel EmailIntegration {\n  id                            String                   @id @default(uuid()) @db.Uuid\n  organization_id               String                   @db.Uuid\n  provider                      EmailIntegrationProvider\n  label                         String\n  email_address                 String\n  status                        EmailIntegrationStatus   @default(DISCONNECTED)\n  /// New inboxes start with scanning off until an administrator turns it on.\n  scanning_enabled              Boolean                  @default(false)\n  auto_upload_enabled           Boolean                  @default(false)\n  scan_interval_minutes         Int                      @default(15)\n  imap_host                     String?\n  imap_port                     Int?\n  imap_use_tls                  Boolean?\n  imap_username                 String?\n  imap_password_encrypted       String?\n  oauth_access_token_encrypted  String?\n  oauth_refresh_token_encrypted String?\n  oauth_token_expires_at        DateTime?\n  oauth_scopes                  String[]                 @default([])\n  /// Provider cursor (IMAP UIDVALIDITY/UID, Gmail historyId) so only new mail is fetched.\n  sync_cursor                   String?\n  scanning_since                DateTime?\n  last_sync_at                  DateTime?\n  last_successful_sync_at       DateTime?\n  last_sync_error               String?\n  connected_by_user_id          String?                  @db.Uuid\n  connected_at                  DateTime?\n  disconnected_at               DateTime?\n  created_at                    DateTime                 @default(now())\n  updated_at                    DateTime                 @updatedAt\n\n  organization Organization @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  connected_by User?        @relation(\"EmailIntegrationConnectedBy\", fields: [connected_by_user_id], references: [id], onDelete: SetNull)\n\n  processed_emails ProcessedEmail[]\n\n  @@unique([organization_id, email_address])\n  @@index([organization_id, status])\n  @@index([scanning_enabled, status])\n  @@map(\"email_integrations\")\n}\n\n/// One synchronized email message. Unique per integration + provider message id to prevent\n/// duplicate processing.\nmodel ProcessedEmail {\n  id                    String               @id @default(uuid()) @db.Uuid\n  organization_id       String               @db.Uuid\n  email_integration_id  String               @db.Uuid\n  provider_message_id   String\n  message_id_header     String?\n  thread_id             String?\n  from_address          String\n  from_name             String?\n  to_addresses          String[]             @default([])\n  subject               String?\n  body_snippet          String?\n  received_at           DateTime\n  status                ProcessedEmailStatus @default(RECEIVED)\n  ignore_reason         String?\n  attachments_count     Int                  @default(0)\n  pdf_attachments_count Int                  @default(0)\n  matched_client_id     String?              @db.Uuid\n  error                 String?\n  processed_at          DateTime?\n  created_at            DateTime             @default(now())\n  updated_at            DateTime             @updatedAt\n\n  organization      Organization     @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  email_integration EmailIntegration @relation(fields: [email_integration_id], references: [id], onDelete: Cascade)\n  matched_client    Client?          @relation(\"ProcessedEmailMatchedClient\", fields: [matched_client_id], references: [id], onDelete: SetNull)\n\n  attachments EmailAttachment[]\n\n  @@unique([email_integration_id, provider_message_id])\n  @@index([organization_id, received_at])\n  @@index([organization_id, status])\n  @@index([organization_id, from_address])\n  @@map(\"processed_emails\")\n}\n\n/// One attachment of a processed email and its classification result.\nmodel EmailAttachment {\n  id                 String                @id @default(uuid()) @db.Uuid\n  organization_id    String                @db.Uuid\n  processed_email_id String                @db.Uuid\n  filename           String\n  mime_type          String\n  size_bytes         Int\n  content_hash       String\n  storage_key        String?\n  status             EmailAttachmentStatus @default(PENDING)\n  extraction_method  TextExtractionMethod  @default(NONE)\n  extracted_text     String?\n  extracted_metadata Json?\n  duplicate_of_id    String?               @db.Uuid\n  document_id        String?               @unique @db.Uuid\n  error              String?\n  processed_at       DateTime?\n  created_at         DateTime              @default(now())\n  updated_at         DateTime              @updatedAt\n\n  organization    Organization      @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  processed_email ProcessedEmail    @relation(fields: [processed_email_id], references: [id], onDelete: Cascade)\n  duplicate_of    EmailAttachment?  @relation(\"EmailAttachmentDuplicate\", fields: [duplicate_of_id], references: [id], onDelete: SetNull)\n  duplicates      EmailAttachment[] @relation(\"EmailAttachmentDuplicate\")\n  document        Document?         @relation(fields: [document_id], references: [id], onDelete: SetNull)\n\n  inbox_item DocumentInboxItem?\n\n  @@index([organization_id, content_hash])\n  @@index([organization_id, status])\n  @@index([processed_email_id])\n  @@map(\"email_attachments\")\n}\n\n// ───────────────────────────────────────────────────────────────────────────────\n// Audit trail & background jobs\n// ───────────────────────────────────────────────────────────────────────────────\n\n/// Append-only audit trail. Not editable by organization users (enforced by API + RLS policy\n/// that allows INSERT/SELECT only).\nmodel ActivityLog {\n  id                   String    @id @default(uuid()) @db.Uuid\n  organization_id      String    @db.Uuid\n  actor_type           ActorType\n  actor_user_id        String?   @db.Uuid\n  actor_client_user_id String?   @db.Uuid\n  /// Dotted action key, e.g. \"client.created\", \"document.approved\", \"reminder.sent\".\n  action               String\n  entity_type          String\n  entity_id            String?   @db.Uuid\n  client_id            String?   @db.Uuid\n  assignment_id        String?   @db.Uuid\n  document_id          String?   @db.Uuid\n  description          String?\n  metadata             Json?\n  ip_address           String?\n  created_at           DateTime  @default(now())\n\n  organization      Organization    @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  actor_user        User?           @relation(\"ActivityLogActorUser\", fields: [actor_user_id], references: [id], onDelete: SetNull)\n  actor_client_user ClientUser?     @relation(\"ActivityLogActorClientUser\", fields: [actor_client_user_id], references: [id], onDelete: SetNull)\n  client            Client?         @relation(fields: [client_id], references: [id], onDelete: SetNull)\n  assignment        FormAssignment? @relation(fields: [assignment_id], references: [id], onDelete: SetNull)\n  document          Document?       @relation(fields: [document_id], references: [id], onDelete: SetNull)\n\n  @@index([organization_id, created_at])\n  @@index([organization_id, client_id, created_at])\n  @@index([organization_id, action])\n  @@index([entity_type, entity_id])\n  @@map(\"activity_logs\")\n}\n\n/// Persistent record of every background job. Redis (BullMQ) holds the live queue state; this\n/// table is the durable history: one row per job attempt with its payload, result, timings,\n/// duration and the worker (\"station\") that processed it. Rows are written when the job is\n/// enqueued and updated on every lifecycle event (active, completed, failed, retry, stalled).\nmodel JobRun {\n  id                   String       @id @default(uuid()) @db.Uuid\n  organization_id      String?      @db.Uuid\n  queue                JobQueue\n  /// Job name inside the queue, e.g. \"notification.deliver\", \"email.extract-text\".\n  job_name             String\n  /// BullMQ job id (also the idempotency key handed to BullMQ).\n  job_id               String\n  status               JobRunStatus @default(QUEUED)\n  trigger              JobTrigger   @default(SYSTEM)\n  attempt              Int          @default(1)\n  max_attempts         Int          @default(3)\n  priority             Int?\n  /// Job input, with secrets and document contents stripped before persisting.\n  payload              Json?\n  result               Json?\n  progress             Int?\n  error_message        String?\n  error_stack          String?\n  /// Worker instance that processed the attempt (hostname:pid / container id).\n  worker_id            String?\n  worker_host          String?\n  worker_pid           Int?\n  /// Domain object the job is about (e.g. \"notification\" / \"email_attachment\" / \"form_assignment\").\n  entity_type          String?\n  entity_id            String?      @db.Uuid\n  /// Job that enqueued this one (pipeline steps: sync → extract → classify → attach).\n  parent_job_run_id    String?      @db.Uuid\n  triggered_by_user_id String?      @db.Uuid\n  queued_at            DateTime     @default(now())\n  scheduled_for        DateTime?\n  started_at           DateTime?\n  finished_at          DateTime?\n  /// Milliseconds spent waiting in the queue (started_at - queued_at).\n  wait_ms              Int?\n  /// Milliseconds of processing time (finished_at - started_at).\n  duration_ms          Int?\n  /// Structured log lines emitted by the processor during the run.\n  logs                 Json?\n  created_at           DateTime     @default(now())\n  updated_at           DateTime     @updatedAt\n\n  organization Organization? @relation(fields: [organization_id], references: [id], onDelete: Cascade)\n  parent       JobRun?       @relation(\"JobRunParent\", fields: [parent_job_run_id], references: [id], onDelete: SetNull)\n  children     JobRun[]      @relation(\"JobRunParent\")\n  triggered_by User?         @relation(\"JobRunTriggeredBy\", fields: [triggered_by_user_id], references: [id], onDelete: SetNull)\n\n  @@unique([queue, job_id, attempt])\n  @@index([organization_id, queue, created_at])\n  @@index([queue, status, created_at])\n  @@index([status, created_at])\n  @@index([job_name, created_at])\n  @@index([entity_type, entity_id])\n  @@index([worker_id, started_at])\n  @@index([parent_job_run_id])\n  @@map(\"job_runs\")\n}\n"
}

